import type { Argv, ArgumentsCamelCase } from 'yargs'
import { Connector, type QueryDisplayValue, type QueryOptions } from '@servicenow/sdk-api'
import { credentialProvider } from '../../auth'
import { logger } from '../../logger'
import { withTelemetryEvent } from '../../telemetry'

interface Arguments {
    table: string
    query: string
    limit: number
    offset: number
    fields?: string
    displayValue: QueryDisplayValue
    excludeReferenceLink: boolean
    noCount: boolean
    timeout: number
    auth?: string
    output?: 'json'
    view?: string
    queryCategory?: string
    queryNoDomain: boolean
}

const DEFAULT_TIMEOUT_MS = 30000

type SuccessEnvelope = {
    ok: true
    hasMore: boolean
    nextOffset: number | null
    records: unknown[]
}

type ErrorEnvelope = {
    ok: false
    error: {
        message: string
        status?: number
        table: string
    }
}

export function builder(yargs: Argv) {
    return yargs
        .positional('table', {
            describe: 'ServiceNow table name (e.g. incident, sys_user)',
            type: 'string',
            demandOption: true,
        })
        .option('query', {
            alias: 'q',
            describe: 'Encoded query string (sysparm_query), e.g. "active=true^priority<=2"',
            type: 'string',
            demandOption: true,
        })
        .option('limit', {
            describe: 'Maximum records per page (sysparm_limit)',
            type: 'number',
            default: 100,
        })
        .option('offset', {
            describe: 'Starting offset (sysparm_offset)',
            type: 'number',
            default: 0,
        })
        .option('fields', {
            alias: 'f',
            describe: 'Comma-separated list of fields to return (sysparm_fields)',
            type: 'string',
        })
        .option('display-value', {
            describe: 'Return display values (sysparm_display_value): "true", "false", or "all" for both',
            choices: ['true', 'false', 'all'] as const,
            default: 'false' as const,
        })
        .option('exclude-reference-link', {
            describe: 'Exclude reference link metadata (sysparm_exclude_reference_link)',
            type: 'boolean',
            default: true,
        })
        .option('no-count', {
            describe: 'Skip total count calculation for better performance (sysparm_no_count)',
            type: 'boolean',
            default: false,
        })
        .option('timeout', {
            describe: 'Per-request timeout in milliseconds. Each page fetch is bounded by this value.',
            type: 'number',
            default: DEFAULT_TIMEOUT_MS,
        })
        .option('view', {
            describe: 'UI view to determine which fields to return (sysparm_view)',
            type: 'string',
        })
        .option('query-category', {
            describe: 'Query category for extended queries (sysparm_query_category)',
            type: 'string',
        })
        .option('query-no-domain', {
            describe: 'Ignore domain separation when querying (sysparm_query_no_domain)',
            type: 'boolean',
            default: false,
        })
        .option('auth', {
            alias: 'a',
            describe: 'Credential alias to use for authentication with instance',
            type: 'string',
        })
        .option('output', {
            alias: 'o',
            describe: 'Output format: json for machine-readable envelope',
            type: 'string',
            choices: ['json'],
        })
}

export async function handler(args: ArgumentsCamelCase<Arguments>): Promise<void> {
    const jsonMode = args.output === 'json'
    if (jsonMode) {
        // Silence logger and only write out result JSON
        logger.setLevel('silent')
    }
    const errorData = { table: args.table, output: args.output ?? 'pretty' }

    try {
        await withTelemetryEvent({ event: 'query', sdkDir: __dirname, errorData }, () => runQuery(args, jsonMode))
    } catch (error) {
        const err = error as Error & { status?: number }
        if (jsonMode) {
            const envelope: ErrorEnvelope = {
                ok: false,
                error: {
                    message: err?.message ?? String(error),
                    ...(typeof err?.status === 'number' ? { status: err.status } : {}),
                    table: args.table,
                },
            }
            console.log(JSON.stringify(envelope))
        } else {
            logger.error(`Failed to query table '${args.table}':`, error)
        }
        process.exitCode = 1
    }
}

async function runQuery(
    args: ArgumentsCamelCase<Arguments>,
    jsonMode: boolean
): Promise<{ table: string; limit: number; jsonMode: boolean }> {
    const options = toQueryOptions(args)
    const credential = await credentialProvider(args.auth)
    const connector = new Connector(credential)
    const result = await connector.queryTable(options)

    if (jsonMode) {
        const envelope: SuccessEnvelope = {
            ok: true,
            hasMore: result.hasMore,
            nextOffset: result.nextOffset,
            records: result.records,
        }
        console.log(JSON.stringify(envelope))
    } else {
        logger.info(`Retrieved ${result.count} record(s) from table '${result.table}'`)
        if (result.hasMore) {
            logger.info(`More records available. Use --offset ${result.nextOffset} to fetch next page`)
        }
        console.log(JSON.stringify(result.records, null, 2))
    }

    return {
        table: args.table,
        limit: args.limit,
        jsonMode,
    }
}

function toQueryOptions(args: ArgumentsCamelCase<Arguments>): QueryOptions {
    const options: QueryOptions = {
        table: args.table,
        encodedQuery: args.query,
        limit: args.limit,
        offset: args.offset,
        displayValue: args.displayValue,
        excludeReferenceLink: args.excludeReferenceLink,
        noCount: args.noCount,
        timeoutMs: args.timeout,
        queryNoDomain: args.queryNoDomain,
    }
    if (args.fields !== undefined) {
        options.fields = args.fields
    }
    if (args.view !== undefined) {
        options.view = args.view
    }
    if (args.queryCategory !== undefined) {
        options.queryCategory = args.queryCategory
    }
    return options
}
